document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){stopClock();saveCurrent();render();}});
root.addEventListener('keydown',ev=>{const dialog=activeDialog();if(!dialog)return;if(ev.key==='Escape'){const close=dialog.querySelector('[data-action="close-modal"],[data-action="close-inspector"],[data-action="set-aside"]');if(close){ev.preventDefault();close.click();}}if(ev.key==='Tab'&&dialog.getAttribute('aria-modal')==='true'){const stops=dialogStops(dialog),first=stops[0],last=stops.at(-1);if(!first){ev.preventDefault();dialog.focus();}else if(ev.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){ev.preventDefault();first.focus();}}});
root.addEventListener('click',async ev=>{let btn=ev.target.closest('[data-action]');if(btn){ev.preventDefault();try{await handle(btn.dataset.action,btn)}catch(e){console.error(e);notify('An unexpected error occurred. You can export a backup from the archive.')}return}if(ev.target.id==='inspector-shade'){inspector=null;if(resumeAfterInspector&&!state?.pending&&state?.status==='alive'){resumeAfterInspector=false;startClock()}render();return}if(ev.target.id==='modal-backdrop'){handle('close-modal',{});}});
